<?php
namespace Divigamana\Services;
final class QwenProvider {
 public function generate(array $service,array $answers,string $locale,array $context=[]): array {
  $started=microtime(true);$q=APP_CONFIG['qwen'];
  $language=$locale==='ta-LK'?'Sri Lankan Tamil':($locale==='en-US'?'English':'fluent Sri Lankan Sinhala');
  $system="You are Divigamana, a culturally respectful Sri Lankan symbolic-reading guide. Write every word in $language, using natural local phrasing. Readings are reflective entertainment, never fact or certainty. Do not guarantee events; diagnose; give medical, legal, financial, safety, fertility, or investment advice; invent planetary positions; claim private knowledge; or tell a person to avoid professional help. Treat third-party information and consent carefully. Return valid JSON only, with exactly this shape: {title:string,disclaimer:string,sections:[{heading:string,body:string}],guidance:string}. Give 3 to 5 concise sections. Make the prose specific to the provided answers and avoid generic horoscope filler.";
  $reference=(string)($context['reading_reference']??bin2hex(random_bytes(8)));
  $prompt="Service: ".json_encode($service['title'],JSON_UNESCAPED_UNICODE)."\nService response policy: ".($service['response_instruction']??'Give a warm personalised structured response.')."\nValidated questionnaire (use only these details): ".json_encode($answers,JSON_UNESCAPED_UNICODE)."\nReading reference: $reference. This is a new reading; choose fresh phrasing and a distinct angle rather than recycling stock wording. Explicitly note any missing birth/chart information as a limitation. The reference is internal: never print it.";
  if(!empty($q['mock_mode'])) return ['result'=>$this->mock($service,$answers,$locale,$reference),'model'=>'mock-development','tokens'=>0,'duration_ms'=>(int)((microtime(true)-$started)*1000)];
  if(empty($q['api_key'])) throw new \RuntimeException('AI service is not configured.');
  $body=['model'=>$q['model'],'messages'=>[['role'=>'system','content'=>$system],['role'=>'user','content'=>$prompt]],'temperature'=>$q['temperature'],'max_tokens'=>$q['max_output_tokens'],'response_format'=>['type'=>'json_object']];
  $base=rtrim((string)$q['base_url'],'/');if(substr($base,-19)!=='/compatible-mode/v1')$base.='/compatible-mode/v1';$ch=curl_init($base.'/chat/completions');curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_HTTPHEADER=>['Authorization: Bearer '.$q['api_key'],'Content-Type: application/json'],CURLOPT_POSTFIELDS=>json_encode($body),CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>(int)$q['timeout_seconds']]);$raw=curl_exec($ch);$status=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);$err=curl_error($ch);curl_close($ch);
  if($raw===false||$status<200||$status>299)throw new \RuntimeException('AI request unavailable'.($err?': '.$err:''));$decoded=json_decode($raw,true);$content=$decoded['choices'][0]['message']['content']??'';$result=json_decode($content,true);if(!is_array($result)||!is_string($result['title']??null)||!is_string($result['disclaimer']??null)||!is_array($result['sections']??null)||!is_string($result['guidance']??null))throw new \RuntimeException('AI returned an invalid structured response.');
  return ['result'=>$result,'model'=>$q['model'],'tokens'=>(int)($decoded['usage']['total_tokens']??0),'duration_ms'=>(int)((microtime(true)-$started)*1000)];
 }
 private function mock(array $s,array $a,string $locale,string $reference):array { $name=$a['full_name']??$a['name']??$a['preferred_name']??''; $si=$locale==='si-LK';$ta=$locale==='ta-LK';$variation=hexdec(substr($reference,-1))%2;$theme=$variation?($si?'අලුත් දෘෂ්ටියක්':($ta?'புதிய பார்வை':'A fresh perspective')):($si?'ඔබේ තේමාව':($ta?'உங்கள் கரு':'Your theme'));return ['title'=>$s['title'][$si?'si':($ta?'ta':'en')],'disclaimer'=>$si?'මෙය සංකේතාත්මක, විනෝදාත්මක විග්‍රහයකි; නිශ්චිත අනාවැකියක් නොවේ.':($ta?'இது குறியீட்டு, பொழுதுபோக்கு விளக்கம்; உறுதியான கணிப்பு அல்ல.':'This is a symbolic, entertainment-focused interpretation—not a certainty.'),'sections'=>[['heading'=>$theme,'body'=>($name?"$name, ":'').($si?'ඔබේ පිළිතුරු ඔබ තුළ ඇති කුතුහලය සහ අර්ථවත් ඉදිරි ගමනක් සඳහා ඇති කැමැත්ත පෙන්වයි.':'your answers suggest curiosity and a wish to move forward with intention.')],['heading'=>$si?'සලකා බැලීම':($ta?'கவனிக்க வேண்டியது':'A gentle reflection'),'body'=>$si?'ඔබට පාලනය කළ හැකි කුඩා පියවර කෙරෙහි අවධානය යොමු කරන්න. උපන් වේලාව හෝ තහවුරු කළ ගණනයන් නොමැති විට නිශ්චිත ග්‍රහ තොරතුරු මෙහි භාවිත කර නැත.':'Focus on small actions within your control. No exact planetary positions have been assumed where verified chart data is unavailable.']], 'guidance'=>$si?'අද ඔබට කරුණාවෙන් හා පැහැදිලිව ඉදිරියට යා හැකි එක් කුඩා පියවරක් තෝරන්න.':'Choose one small, kind and practical step for today.']; }
}
